use super::*;
use super::tests::field;
fn wreck()->Game{let mut g=field();g.objects=vec![json!({"type":6,"equipmentId":255,"nativeSlot":0,"x":1000,"y":1200,"nativeHp":1,"nativeFlags13":0x70})];g.import_native_world(&Value::Null);g}
fn freeze_teams(g:&mut Game){for team in 0..2{g.spawn("grunt",team,200.+team as f64*1200.,200.,team as usize+1,None);}g.maintain_native_group_rosters();for m in g.native_group_rosters.members.iter_mut().flatten(){m.flags69|=64;}g.ai_teams.clear();}
#[test]fn real_object_callback_keeps_all_six_rows_without_snapshot_rng_or_later_state_rewrites(){
 let mut g=wreck();g.multiplayer=true;g.native_flag_frame=3;g.native_object_frame=5;g.native_world.as_mut().unwrap().objects[0].as_mut().unwrap().variant26=3;let crt=g.native_cosmetic_rng;g.update_native_world_objects();let rows=g.native_display.objects.clone().unwrap();assert_eq!(rows.len(),6);assert_eq!((rows[0].0.sprite,rows[1].0.sprite,rows[2].0.sprite),(512,1785,1805));assert!(rows[1..].iter().all(|(_,r)|r["nativeLiteralPalette"]==true&&r["palette"]==0));assert_eq!(g.native_ambient_animations.records[0].position(),[504,608]);
 let a=g.native_display_queue();let b=g.native_display_queue();assert_eq!(a,b);assert_eq!(g.native_cosmetic_rng,crt);assert_eq!(g.native_ambient_animations.records.iter().filter(|r|r.active()).count(),1);let o=g.native_world.as_mut().unwrap().objects[0].as_mut().unwrap();o.active=false;o.record.position[0]=-1;assert_eq!(g.native_display_queue(),a,"later retirement cannot erase the already submitted OBJECT picture");g.update_native_world_objects();assert!(g.native_display.objects.as_ref().unwrap().is_empty());
}
#[test]fn spark_probe_and_real_150_pool_keep_the_crt_draws_for_free_full_and_duplicate_cases(){
 for mode in 0..3{let mut g=wreck();g.native_cosmetic_rng=106;if mode==1{for(i,r)in g.native_ambient_animations.records.iter_mut().enumerate(){r.set_word(0,100+i as i16);}}if mode==2{for o in[0,4,8]{g.native_ambient_animations.records[1].set_word(o,504);g.native_ambient_animations.records[1].set_word(o+2,608);}}g.update_native_world_objects();assert_eq!(g.native_cosmetic_rng,2158666292,"outer384 probe and inner170 CRT draws happen before full/duplicate admission");assert_eq!(g.native_display.objects.as_ref().unwrap().len(),6);assert_eq!(g.native_ambient_animations.records[0].word(0),if mode==0{504}else if mode==1{100}else{-1});if mode==0{assert_eq!(g.native_ambient_animations.records[0].word(20),2895);}}
 let mut g=wreck();g.native_cosmetic_rng=1;g.update_native_world_objects();assert_eq!(g.native_cosmetic_rng,2745024);assert!(g.native_ambient_animations.records.iter().all(|r|!r.active()));
}
#[test]fn invisible_uncolored_expired_and_invalid_overlay_inputs_do_not_guess_a_spark(){
 for mode in 0..4{let mut g=wreck();if mode==0{g.native_view=Some(([2000,2000],[1024,1024]));}if mode==1{g.native_world.as_mut().unwrap().objects[0].as_mut().unwrap().record.flags13=0x80;}if mode==2{g.native_world.as_mut().unwrap().objects[0].as_mut().unwrap().lifetime24=1;}if mode==3{g.native_world.as_mut().unwrap().objects[0].as_mut().unwrap().variant26=4;}let crt=g.native_cosmetic_rng;g.update_native_world_objects();assert_eq!(g.native_cosmetic_rng,crt);assert!(g.native_display.objects.as_ref().unwrap().len()<=1);if mode==3{assert_eq!(g.native_route_boundary,Some(super::super::original_path_contact::game::Boundary::ObjectOverlayVariant(0,4)));}}
}
#[test]fn raw_object_variant_survives_constructor_mission_retirement_and_fire_recycling(){
 let mut g=wreck();{let o=g.native_world.as_mut().unwrap().objects[0].as_mut().unwrap();o.variant26=3;o.flags26=165;}
 g.objects.clear();g.import_native_world(&Value::Null);let o=g.native_world.as_ref().unwrap().objects[0].as_ref().unwrap();assert_eq!((o.record.position[0],o.variant26,o.flags26),(-1,3,165));assert_eq!(g.reserve_native_world_fire_slot(),Some(0));assert_eq!(g.native_world.as_ref().unwrap().objects[0].as_ref().unwrap().variant26,3);
 g.objects=vec![json!({"type":6,"equipmentId":255,"nativeSlot":0,"x":1000,"y":1200,"nativeHp":1,"nativeFlags13":0x70})];g.import_native_world(&Value::Null);assert_eq!(g.native_world.as_ref().unwrap().objects[0].as_ref().unwrap().variant26,3);
}
#[test]fn actual_58af0_conversion_writes_variant26_without_overwriting_the_old_flags1a(){
 for mp in[false,true]{let mut g=field();g.multiplayer=mp;g.import_native_world(&Value::Null);let mut old=g.make_object(6,[500,600],1).unwrap();old.active=false;old.record.position[0]=-1;old.flags26=165;old.variant26=3;g.native_world.as_mut().unwrap().objects[0]=Some(old);g.spawn("medium",1,640.,640.,1,None);g.units[0].hp=-1.;let before=g.units[0].clone();g.original_rng.multiplayer=mp;let mut expected=g.original_rng.clone();let variant=(expected.next_u32()&3)as i8;g.native_removed_hardware_mode(0,&before,false,false,false);let o=g.native_world.as_ref().unwrap().objects[0].as_ref().unwrap();assert_eq!((o.kind,o.flags26,o.variant26,o.lifetime24),(6,165,variant,288));assert_eq!(g.original_rng.words,expected.words);}
}
#[test]fn eighteen_real_main_callbacks_keep_the_native_six_eight_and_four_clocks_distinct(){
 let mut g=field();freeze_teams(&mut g);for t in 1..=18{g.step(0.059);assert_eq!((g.native_object_frame,g.native_wait_clock,g.native_flag_frame,g.native_callback_mode),((t%6)as i8,(t%8)as i8,((t+1)/2%4)as i16,if t%2==1{255}else{0}),"callback{t}");}for(before,after)in[(-1,0),(5,0),(6,7),(127,-128)]{g.native_object_frame=before;g.step(0.059);assert_eq!(g.native_object_frame,after,"434ac9 compares equality with6, without masking a warm value");}
}
